def reprendre_donnees(apps, schema_editor):
    Bien, Syndic = apps.get_model("patrimoine", "Bien"), apps.get_model("patrimoine", "Syndic")
    # « FONCIA (Craponne) » devient le syndic FONCIA à Craponne, partagé par les biens qui ont le même texte
    for bien in Bien.objects.exclude(syndic_texte=""):
        m = re.match(r"^(.*?)\s*\(([^()]*)\)$", bien.syndic_texte.strip())
        nom, ville = (m.group(1), m.group(2)) if m else (bien.syndic_texte.strip(), "")
        bien.syndic, _ = Syndic.objects.get_or_create(nom=nom, ville=ville)
        bien.save(update_fields=["syndic"])
    # loyer initial : loyer avant la première révision enregistrée, sinon loyer actuel
    Bail, Revision = apps.get_model("patrimoine", "Bail"), apps.get_model("patrimoine", "RevisionLoyer")
    for bail in Bail.objects.all():
        premiere = Revision.objects.filter(bail=bail).order_by("date_effet").first()
        bail.loyer_initial = premiere.ancien_loyer if premiere else bail.loyer_hc
        bail.save(update_fields=["loyer_initial"])
    apps.get_model("patrimoine", "SiteUtile").objects.get_or_create(
        nom="Indice IRL", defaults={"url": "https://www.anil.org/outils/indices-et-plafonds/tableau-de-lirl/", "ordre": 1})


